path = r"C:\Users\iman\Downloads\aut-education\src\app\teacher\battle-questions\page.tsx"
with open(path, "w", encoding="utf-8") as f:
    f.write("import { useEffect, useState } from 'react';\nimport { supabase } from '@/lib/supabase';\n\nexport default function TeacherBattleQuestionsPage() {\n  const [questions, setQuestions] = useState<Array<any>>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [creating, setCreating] = useState(false);\n  const [form, setForm] = useState({ title: '', description: '', hint: '', difficulty: 'medium' as 'easy' | 'medium' | 'hard', test_cases: [] as Array<{input:string;expected:string}>, tags: [] as string[], class_id: '' });\n  useEffect(() => { fetchQuestions(); }, []);\n  async function fetchQuestions() { setLoading(true); setError(null); try { const { data: { user } } = await supabase.auth.getUser(); if (!user) throw new Error('Not authenticated'); const { data, error } = await supabase.from('battle_questions').select('*').eq('teacher_id', user.id).order('created_at', { ascending: false }); if (error) throw error; setQuestions(data ?? []); } catch (err: any) { setError(err.message ?? 'Unknown error'); } finally { setLoading(false); } }\n  function handleCreateOpen() { setCreating(true); setForm({ title: '', description: '', hint: '', difficulty: 'medium', test_cases: [], tags: [], class_id: '' }); }\n  function handleCreateClose() { setCreating(false); }\n  async function handleCreateSubmit(e: React.FormEvent) { e.preventDefault(); setLoading(true); setError(null); try { const { data, error } = await supabase.from('battle_questions').insert({ title: form.title, description: form.description, hint: form.hint, difficulty: form.difficulty, test_cases: form.test_cases, tags: form.tags, is_active: true, class_id: form.class_id, teacher_id: (await supabase.auth.getUser()).data.user?.id }).select().single(); if (error) throw error; await fetchQuestions(); setCreating(false); } catch (err: any) { setError(err.message ?? 'Unknown error'); } finally { setLoading(false); } }\n  async function handleDelete(id: string) { if (!window.confirm('حذف؟')) return; setLoading(true); try { const { error } = await supabase.from('battle_questions').delete().eq('id', id); if (error) throw error; await fetchQuestions(); } catch (err: any) { setError(err.message); } finally { setLoading(false); } }\n  if (loading) return <div className=\"p-6\">Loading...</div>;\n  if (error) return <div className=\"p-6 text-red-600\">Error: {error}</div>;\n  return ( <div className=\"p-6\">\n    <div className=\"flex justify-between items-center mb-4\">\n      <h1 className=\"text-2xl font-bold\">بانک سوال مسابقاتی</h1>\n      <button onClick={handleCreateOpen} className=\"btn btn-primary px-4 py-2 rounded\">+ ایجاد سوال جدید</button>\n    </div>\n    {creating && ( <div className=\"mt-6 p-4 bg-gray-50 rounded\"><h2 className=\"text-xl font-semibold mb-4\">ایجاد سوال جدید</h2><form onSubmit={handleCreateSubmit} className=\"space-y-4\"><div><label className=\"block text-sm font-medium mb-1\">عنوان</label><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className=\"w-full px-3 py-2 border border-gray-300 rounded\" required /></div><div><label className=\"block text-sm font-medium mb-1\">توضیحات</label><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} className=\"w-full px-3 py-2 border border-gray-300 rounded\" rows={3} /></div><div><label className=\"block text-sm font-medium mb-1\">راهنمایی</label><input value={form.hint} onChange={e=>setForm({...form,hint:e.target.value})} className=\"w-full px-3 py-2 border border-gray-300 rounded\" /></div><div className=\"flex items-baseline gap-4\"><div><label className=\"block text-sm font-medium mb-1\">دشواری</label><select value={form.difficulty} onChange={e=>setForm({...form,difficulty:e.target.value as any})} className=\"w-full px-3 py-2 border border-gray-300 rounded\"><option value=\"easy\">آسان</option><option value=\"medium\">متوسط</option><option value=\"hard\">سخت</option></select></div><div><label className=\"block text-sm font-medium mb-1\">کلاس ID</label><input value={form.class_id} onChange={e=>setForm({...form,class_id:e.target.value})} className=\"w-full px-3 py-2 border border-gray-300 rounded\" /></div></div><div><label className=\"block text-sm font-medium mb-1\">تست‌کیس‌ها (JSON)</label><textarea value={JSON.stringify(form.test_cases,null,2)} onChange={e=>{try{setForm({...form,test_cases:JSON.parse(e.target.value)});}catch{}}} className=\"w-full px-3 py-2 border border-gray-300 rounded\" rows={4} placeholder='[{\"input\":\"...\",\"expected\":\"...\"}]' /></div><div><label className=\"block text-sm font-medium mb-1\">برچسب‌ها (JSON)</label><textarea value={JSON.stringify(form.tags,null,2)} onChange={e=>{try{setForm({...form,tags:JSON.parse(e.target.value)});}catch{}}} className=\"w-full px-3 py-2 border border-gray-300 rounded\" rows={2} placeholder='[\"tag1\",\"tag2\"]' /></div><div className=\"flex justify-end\"><button type=\"button\" onClick={handleCreateClose} className=\"mr-2 btn btn-secondary px-3 py-2 rounded\">انصراف</button><button type=\"submit\" disabled={loading} className=\"btn btn-success px-3 py-2 rounded\">ایجاد</button></div></form></div> ) }\n    {questions.length === 0 ? <p className=\"text-gray-600\">هیچ سوالی اضافه نشده است.</p> : ( <div className=\"space-y-4 mt-6\">{questions.map((q)=> <div key={q.id} className=\"border p-4 rounded-lg bg-white\"><div className=\"flex justify-between items-start\"><div><h2 className=\"font-semibold\">{q.title}</h2>{q.description && <p className=\"text-sm text-gray-600 mt-1\">{q.description}</p>}{q.hint && <p className=\"text-sm text-blue-600 mt-1\"><span className=\"font-medium\">راهنمایی:</span> {q.hint}</p>}</div><div className=\"text-right\"><button onClick={()=>handleDelete(q.id)} className=\"btn btn-error px-3 py-2 rounded\">حذف</button></div></div></div> )}</div> )}\n  </div> );\n}\n")
print("rewrote")
